    static void बिघाड_मूल्य(String शब्द_मजकूर) {
        if (त्रुटी) return;
        int वर्गवारी_संहिता = 0;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "ArithmeticException: / by zero")) वर्गवारी_संहिता = 4;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "NullPointerException") || जावा_साधने.समान_मजकूर(शब्द_मजकूर, "null or invalid array")) वर्गवारी_संहिता = 5;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "ArrayIndexOutOfBoundsException")) वर्गवारी_संहिता = 7;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "StringIndexOutOfBoundsException")) वर्गवारी_संहिता = 8;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "NumberFormatException")) वर्गवारी_संहिता = 10;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "FileNotFoundException: file open failed")) वर्गवारी_संहिता = 12;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "IOException: stream closed") || जावा_साधने.समान_मजकूर(शब्द_मजकूर, "IOException: read failed") || जावा_साधने.समान_मजकूर(शब्द_मजकूर, "IOException: write failed")) वर्गवारी_संहिता = 11;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "ClassCastException")) वर्गवारी_संहिता = 14;
        if (जावा_साधने.समान_मजकूर(शब्द_मजकूर, "NegativeArraySizeException")) वर्गवारी_संहिता = 15;
        if (वर्गवारी_संहिता != 0 && फ्रेम_अनुक्रमणिका >= 0) { अपवादउद्भवा_अपवाद(वर्गवारी_संहिता, शब्द_मजकूर); return; }
        प्रयोक्ता.लेखन("JVM error: "); प्रयोक्ता.लेखन(शब्द_मजकूर); प्रयोक्ता.वर्ण_मूल्य_लिहा(10); त्रुटी = true;
    }
    static boolean क्लिप(int सुरू_करा, int लांबी_मूल्य) {
        if (सुरू_करा < 0 || सुरू_करा >= फाइल.length || लांबी_मूल्य < 0) return false;
        int वर्ग_व्याख्या = सुरू_करा / 16384;
        return सुरू_करा % 16384 <= वर्ग_व्याख्या_आकारा[वर्ग_व्याख्या] && लांबी_मूल्य <= वर्ग_व्याख्या_आकारा[वर्ग_व्याख्या] - सुरू_करा % 16384;
    }
    static int बाइट_मूल्य() {
        if (!क्लिप(स्थान_वाचा, 1)) { बिघाड_मूल्य("truncated class file"); return 0; }
        return फाइल[स्थान_वाचा++];
    }
    static int लघु_मूल्य() { return बाइट_मूल्य() << 8 | बाइट_मूल्य(); }
    static int पूर्णांक() { return लघु_मूल्य() << 16 | लघु_मूल्य(); }
    static void वगळा_बाइट(int लांबी_मूल्य) { if (!क्लिप(स्थान_वाचा, लांबी_मूल्य)) बिघाड_मूल्य("invalid attribute size"); else स्थान_वाचा += लांबी_मूल्य; }
    static boolean स्थिरांक_तपासा(int संख्या, int प्रकार_मूल्य) {
        if (संख्या <= 0 || संख्या >= स्थिरांक_टॅग.length || स्थिरांक_टॅग[संख्या] != प्रकार_मूल्य) { बिघाड_मूल्य("invalid constant pool reference"); return false; }
        return true;
    }
    static boolean मजकूर_व्याप्ती(int सुरू_करा, int लांबी_मूल्य, String शब्द_मजकूर) {
        if (!क्लिप(सुरू_करा, लांबी_मूल्य)) return false;
        int कर्सर_वाचा = सुरू_करा, शेवट = सुरू_करा + लांबी_मूल्य;
        for (int लूप_अनुक्रमणिका = 0; लूप_अनुक्रमणिका < शब्द_मजकूर.length(); लूप_अनुक्रमणिका++) {
            int वर्ण_कोड = शब्द_मजकूर.charAt(लूप_अनुक्रमणिका);
            if (वर्ण_कोड > 0 && वर्ण_कोड < 128) { if (कर्सर_वाचा >= शेवट || फाइल[कर्सर_वाचा++] != वर्ण_कोड) return false; }
            else if (वर्ण_कोड < 2048) {
                if (कर्सर_वाचा + 2 > शेवट || फाइल[कर्सर_वाचा++] != (192 | (वर्ण_कोड >> 6)) || फाइल[कर्सर_वाचा++] != (128 | (वर्ण_कोड & 63))) return false;
            } else if (कर्सर_वाचा + 3 > शेवट || फाइल[कर्सर_वाचा++] != (224 | (वर्ण_कोड >> 12)) || फाइल[कर्सर_वाचा++] != (128 | ((वर्ण_कोड >> 6) & 63)) || फाइल[कर्सर_वाचा++] != (128 | (वर्ण_कोड & 63))) return false;
        }
        return कर्सर_वाचा == शेवट;
    }
    static boolean शब्द_मजकूर(int स्थिरांक_मूल्य, String शब्द_मजकूर) { return स्थिरांक_तपासा(स्थिरांक_मूल्य, 1) && मजकूर_व्याप्ती(स्थिरांक_पहिले_मूल्य[स्थिरांक_मूल्य], स्थिरांक_दुसरे_मूल्य[स्थिरांक_मूल्य], शब्द_मजकूर); }
    static boolean जुळणारे_शब्द(int पहिले_संकार्य, int दुसरे_संकार्य) {
        if (!स्थिरांक_तपासा(पहिले_संकार्य, 1) || !स्थिरांक_तपासा(दुसरे_संकार्य, 1) || स्थिरांक_दुसरे_मूल्य[पहिले_संकार्य] != स्थिरांक_दुसरे_मूल्य[दुसरे_संकार्य]) return false;
        for (int संख्या = 0; संख्या < स्थिरांक_दुसरे_मूल्य[पहिले_संकार्य]; संख्या++) if (फाइल[स्थिरांक_पहिले_मूल्य[पहिले_संकार्य] + संख्या] != फाइल[स्थिरांक_पहिले_मूल्य[दुसरे_संकार्य] + संख्या]) return false;
        return true;
    }
    static int वर्ग_नाव_मजकूर(int संख्या) { return स्थिरांक_तपासा(संख्या, 7) && स्थिरांक_तपासा(स्थिरांक_पहिले_मूल्य[संख्या], 1) ? स्थिरांक_पहिले_मूल्य[संख्या] : 0; }
    static int संदर्भ_नाव(int संख्या) { return स्थिरांक_तपासा(संख्या, 12) && स्थिरांक_तपासा(स्थिरांक_पहिले_मूल्य[संख्या], 1) ? स्थिरांक_पहिले_मूल्य[संख्या] : 0; }
    static int संदर्भ_टाइप_करा(int संख्या) { return स्थिरांक_तपासा(संख्या, 12) && स्थिरांक_तपासा(स्थिरांक_दुसरे_मूल्य[संख्या], 1) ? स्थिरांक_दुसरे_मूल्य[संख्या] : 0; }
    static int विवरणक_टाइप_करा(int शेवट, boolean रिक्त_टाइप_करा) {
        if (स्थान_वाचा >= शेवट) { बिघाड_मूल्य("invalid descriptor"); return 0; }
        int मूल्य = बाइट_मूल्य();
        if (मूल्य == 'V' && रिक्त_टाइप_करा) return 0;
        if (मूल्य == 'I' || मूल्य == 'B' || मूल्य == 'C' || मूल्य == 'S' || मूल्य == 'Z') return 1;
        if (मूल्य == '[') { विवरणक_टाइप_करा(शेवट, false); return 2; }
        if (मूल्य == 'L') {
            int सुरू_करा = स्थान_वाचा;
            while (स्थान_वाचा < शेवट && फाइल[स्थान_वाचा] != ';') स्थान_वाचा++;
            if (स्थान_वाचा == शेवट || स्थान_वाचा == सुरू_करा) बिघाड_मूल्य("invalid reference descriptor");
            else स्थान_वाचा++;
            return 2;
        }
        बिघाड_मूल्य("unsupported descriptor type"); return 0;
    }
    static void विवरणक_वाचा(int फलन_मूल्य) {
        int मागील_आयटम = स्थान_वाचा, संख्या = पद्धत_टाइप_करा[फलन_मूल्य];
        if (!स्थिरांक_तपासा(संख्या, 1)) return;
        स्थान_वाचा = स्थिरांक_पहिले_मूल्य[संख्या]; int शेवट = स्थान_वाचा + स्थिरांक_दुसरे_मूल्य[संख्या];
        if (बाइट_मूल्य() != '(') बिघाड_मूल्य("invalid method descriptor");
        int आयटम_संख्या = 0;
        while (!त्रुटी && स्थान_वाचा < शेवट && फाइल[स्थान_वाचा] != ')') {
            if (आयटम_संख्या == 16) { बिघाड_मूल्य("too many method arguments"); break; }
            पद्धत_वितर्क_टाइप_करा[फलन_मूल्य * 16 + आयटम_संख्या++] = विवरणक_टाइप_करा(शेवट, false);
        }
        if (स्थान_वाचा >= शेवट || बाइट_मूल्य() != ')') बिघाड_मूल्य("invalid method descriptor");
        पद्धत_परतकरा[फलन_मूल्य] = विवरणक_टाइप_करा(शेवट, true); पद्धत_वितर्क_संख्या[फलन_मूल्य] = आयटम_संख्या;
        if (स्थान_वाचा != शेवट) बिघाड_मूल्य("invalid method descriptor");
        स्थान_वाचा = मागील_आयटम;
    }
    static int स्थिरांक_अनुक्रमणिका_वाचा() { int मूल्य = लघु_मूल्य(); return मूल्य == 0 ? 0 : सध्याचे_व्याकरणविश्लेषित_वर्ग * 512 + मूल्य; }
    static int क्रियासंकेत_स्थिरांक_वाचा() { return पद्धत_मालक[फ्रेम_पद्धत[फ्रेम_अनुक्रमणिका]] * 512 + क्रियासंकेत_लघु_वाचा(); }
    static void वगळा_गुणधर्म() {
        int आयटम_संख्या = लघु_मूल्य();
        for (int संख्या = 0; संख्या < आयटम_संख्या && !त्रुटी; संख्या++) { स्थिरांक_तपासा(स्थिरांक_अनुक्रमणिका_वाचा(), 1); वगळा_बाइट(पूर्णांक()); }
    }
    static int आज्ञा_लांबी(int मूल्य) {
        if (मूल्य == 16 || मूल्य == 18 || मूल्य == 21 || मूल्य == 25 || मूल्य == 54 || मूल्य == 58 || मूल्य == 188) return 2;
        if (मूल्य == 17 || मूल्य == 19 || मूल्य == 132 || मूल्य >= 153 && मूल्य <= 167
            || मूल्य >= 178 && मूल्य <= 184 || मूल्य == 187 || मूल्य == 189 || मूल्य == 192 || मूल्य == 193 || मूल्य == 198 || मूल्य == 199) return 3;
        if (मूल्य == 185 || मूल्य == 200) return 5;
        if (मूल्य >= 0 && मूल्य <= 8 || मूल्य >= 26 && मूल्य <= 29 || मूल्य >= 42 && मूल्य <= 46 || मूल्य >= 50 && मूल्य <= 53
            || मूल्य >= 59 && मूल्य <= 62 || मूल्य >= 75 && मूल्य <= 79 || मूल्य >= 83 && मूल्य <= 95
            || मूल्य == 96 || मूल्य == 100 || मूल्य == 104 || मूल्य == 108 || मूल्य == 112 || मूल्य == 116
            || मूल्य == 120 || मूल्य == 122 || मूल्य == 124 || मूल्य == 126 || मूल्य == 128 || मूल्य == 130
            || मूल्य >= 145 && मूल्य <= 147 || मूल्य == 172 || मूल्य == 176 || मूल्य == 177 || मूल्य == 190 || मूल्य == 191
            || मूल्य == 194 || मूल्य == 195) return 1;
        return 0;
    }
